/// <summary>
/// MPJ_28395_Stock reservation - 29/07/2022
/// Class <c>METSalesOrderAutoReserveUIBuilder</c> contains all UI functionality
/// </summary>
class METSalesOrderAutoReserveUIBuilder extends SysOperationAutomaticUIBuilder
{
    METSalesOrderAutoReserveContract   contract;
    
}

Method.Source:
    /// <summary>
    /// Overriden the <c>postBuild</c> method to disable <c>METReserveDaysPriorShipDate</c> field
    /// </summary>
    public void postBuild()
    {
        DialogField dialogField;

        super();

        contract = this.dataContractObject();
        
        dialogField = this.bindInfo().getDialogField(contract, methodStr(METSalesOrderAutoReserveContract, parmMETReserveDaysPriorShipDate));
        dialogField.enabled(false);
        dialogField.value(SalesParameters::find().METReserveDaysPriorShipDate);
    }
